import { ChangeDetectionStrategy, ChangeDetectorRef, Component, Input, OnDestroy, OnInit } from '@angular/core';
import { Subscription } from 'rxjs';
import { JxCustomFooterBase, JxFooterCellContext } from 'jx-cell';

/**
 * CollapsibleFooterToggleComponent
 *
 * Componente footer che funge da intestazione collassabile.
 * Quando cliccato, comprime o espande tutte le righe footer
 * successive alla propria riga (`fy + 1 ... N`).
 *
 * Utilizzo in app.component.ts:
 * ```typescript
 * footers: [
 *   [{ value: 'Dettagli', colspan: 16, footerComponent: CollapsibleFooterToggleComponent }],
 *   ['', '=SUM(B1:B12)', '=SUM(C1:C12)', ...],  // ← queste vengono nascoste/mostrate
 *   ['', 'Altro',        '=AVG(C1:C12)', ...],
 * ]
 * ```
 *
 * Il componente legge `context.fy` per sapere su quale riga si trova
 * e usa `context.api.toggleFooterGroup(fy)` per collassare/espandere.
 *
 * Le opzioni `context.column.options` possono personalizzare il comportamento:
 * - `label`: testo mostrato accanto al toggle (default: valore della cella)
 * - `collapsedByDefault`: se true, inizia collassato (default: false)
 */
@Component({
  standalone: false,
  selector: 'app-collapsible-footer-toggle',
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <button
      class="cft-btn"
      type="button"
      [title]="collapsed ? 'Espandi' : 'Comprimi'"
      (click)="toggle()"
    >
      <span class="cft-icon">{{ collapsed ? '▶' : '▼' }}</span>
      <span class="cft-label">{{ label }}</span>
      <span class="cft-badge" *ngIf="hiddenCount > 0">
        {{ hiddenCount }} {{ hiddenCount === 1 ? 'riga nascosta' : 'righe nascoste' }}
      </span>
    </button>
  `,
  styles: [`
    .cft-btn {
      display: flex;
      align-items: center;
      gap: 6px;
      background: none;
      border: none;
      cursor: pointer;
      padding: 2px 4px;
      color: inherit;
      font: inherit;
      font-weight: 600;
      width: 100%;
      text-align: left;
      border-radius: 3px;
      transition: background 0.15s;
    }
    .cft-btn:hover { background: rgba(255,255,255,0.08); }
    .cft-btn:active { background: rgba(255,255,255,0.15); }

    .cft-icon {
      font-size: 9px;
      opacity: 0.7;
      flex-shrink: 0;
      transition: transform 0.2s;
    }
    .cft-label {
      flex: 1;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }
    .cft-badge {
      font-size: 10px;
      font-weight: 400;
      opacity: 0.6;
      white-space: nowrap;
      flex-shrink: 0;
    }
  `],
})
export class CollapsibleFooterToggleComponent extends JxCustomFooterBase implements OnInit, OnDestroy {
  @Input() override context: JxFooterCellContext = undefined!;

  collapsed = false;

  private sub = new Subscription();

  constructor(private readonly cdr: ChangeDetectorRef) { super(); }

  ngOnInit(): void {
    const api = this.context?.api;
    // Inizializzazione stato collassato da options
    const opts: any = this.context?.column?.options ?? {};
    if (opts['collapsedByDefault']) {
      this.collapsed = true;
      // Applica subito la visibilità — schedulato per evitare ExpressionChangedAfterCheck
      setTimeout(() => { api?.toggleFooterGroup(this.context.fy); this.cdr.markForCheck(); }, 0);
    }
    // Sincronizza lo stato se il workbook aggiorna i footers (es. dopo recalculate)
    if (api?.footers$) {
      this.sub.add(api.footers$.subscribe(() => {
        this.collapsed = !!api.isFooterGroupCollapsed?.(this.context.fy);
        this.cdr.markForCheck();
      }));
    }
  }

  ngOnDestroy(): void { this.sub.unsubscribe(); }

  toggle(): void {
    const api = this.context?.api;
    if (!api?.toggleFooterGroup) return;
    this.collapsed = api.toggleFooterGroup(this.context.fy);
    this.cdr.markForCheck();
  }

  get label(): string {
    const opts: any = this.context?.column?.options ?? {};
    if (opts['label']) return String(opts['label']);
    return this.displayValue != null ? String(this.displayValue) : '';
  }

  /** Quante righe sono nascoste dal gruppo controllato da questa riga. */
  get hiddenCount(): number {
    const api = this.context?.api;
    if (!this.collapsed || !api?.getFooters) return 0;
    const total = (api.getFooters() as any[][]).length;
    return Math.max(0, total - this.context.fy - 1);
  }
}
