import { ChangeDetectorRef, Component, Input, OnInit } from '@angular/core';
import {
  JxBeforeEditionEndPayload,
  JxCancellableEvent,
  JxCellLifecycle,
  JxChangePayload,
  JxCustomCellBase,
  JxCustomCellContext,
  JxEditionEndPayload,
  JxEditionStartPayload,
} from 'jx-cell';

interface DemoRow extends Record<string, any> {
  text?: string;
  priority?: string;
}

type PriorityLevel = '—' | '🟢 Bassa' | '🟡 Media' | '🔴 Alta' | '🚨 Critica';

/**
 * Demo — Priority Cell with JxCellLifecycle hooks
 *
 * Dimostra l'utilizzo dell'interfaccia JxCellLifecycle per intercettare
 * gli eventi del foglio di calcolo dalla cella stessa.
 *
 * Hooks attivi:
 *  - jxOnBeforeChange    → blocca "🚨 Critica" se la colonna "Text" è vuota
 *  - jxOnChange          → aggiorna il log interno
 *  - jxOnEditorOpen      → nota apertura editor (solo per questa cella)
 *  - jxOnBeforeEditorClose → può trasformare il valore prima del salvataggio
 *  - jxOnEditorClose     → aggiorna il log dopo salvataggio
 *
 * Il log degli ultimi 3 eventi è visibile direttamente nella cella.
 */
@Component({
  standalone: false,
  selector: 'app-priority-cell',
  template: `
    <div class="pc-root" [class.pc-disabled]="!editable">
      <!-- Badge principale: click ciclico -->
      <button
        type="button"
        class="pc-badge"
        [class.pc-low]="isPriority('🟢 Bassa')"
        [class.pc-mid]="isPriority('🟡 Media')"
        [class.pc-high]="isPriority('🔴 Alta')"
        [class.pc-critical]="isPriority('🚨 Critica')"
        [disabled]="!editable"
        (click)="cycle($event)"
        (keydown.enter)="cycle($event)"
        (keydown.space)="cycle($event)"
        title="Click per cambiare priorità"
      >{{ currentLabel }}</button>

      <!-- Log eventi (ultimi 3) -->
      <div class="pc-log" *ngIf="log.length">
        <span *ngFor="let l of log" class="pc-log-entry">{{ l }}</span>
      </div>
    </div>
  `,
  styles: [`
    .pc-root {
      display: flex;
      flex-direction: column;
      gap: 2px;
      padding: 2px;
      font-size: 11px;
      min-height: 26px;
    }
    .pc-disabled { opacity: 0.5; }

    .pc-badge {
      border: none;
      border-radius: 10px;
      padding: 1px 8px;
      font-size: 11px;
      cursor: pointer;
      white-space: nowrap;
      background: #e0e0e0;
      color: #333;
      transition: background 0.15s;
    }
    .pc-badge:disabled { cursor: default; }
    .pc-low      { background: #d4edda; color: #155724; }
    .pc-mid      { background: #fff3cd; color: #856404; }
    .pc-high     { background: #f8d7da; color: #721c24; }
    .pc-critical { background: #c82333; color: #fff; font-weight: 700; }

    .pc-log {
      display: flex;
      flex-direction: column;
      gap: 0;
    }
    .pc-log-entry {
      font-size: 9px;
      color: #666;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
      line-height: 1.3;
    }
  `],
})
export class PriorityCellComponent
  extends JxCustomCellBase<DemoRow>
  implements OnInit, JxCellLifecycle
{
  @Input() override context: JxCustomCellContext<DemoRow> = undefined!;

  /** Ultimi 3 eventi ricevuti — visibili direttamente nella cella. */
  log: string[] = [];

  private readonly levels: PriorityLevel[] = ['—', '🟢 Bassa', '🟡 Media', '🔴 Alta', '🚨 Critica'];

  constructor(private cdr: ChangeDetectorRef) {
    super();
  }

  ngOnInit(): void {
    /**
     * wireLifecycle() legge quali metodi jxOn* sono stati definiti su questa
     * istanza e si abbona solo agli stream corrispondenti.
     * Tutta la cleanup è gestita da ngOnDestroy() della base class.
     */
    this.wireLifecycle();
  }

  // ────────────────────────────────────────────────────────────────────────
  // Helpers
  // ────────────────────────────────────────────────────────────────────────

  get currentLabel(): string {
    return this.levels.includes(this.value as PriorityLevel) ? this.value : '—';
  }

  isPriority(level: PriorityLevel): boolean {
    return this.value === level;
  }

  /** Avanza al livello successivo (wraparound). */
  cycle(event?: Event): void {
    this.stopEvent(event);
    if (!this.editable) return;

    const idx = this.levels.indexOf(this.value as PriorityLevel);
    const next = this.levels[(idx + 1) % this.levels.length];
    this.commitValue(next, false); // commitValue chiama setValue → beforeChange$ + change$
  }

  // ────────────────────────────────────────────────────────────────────────
  // JxCellLifecycle hooks
  // ────────────────────────────────────────────────────────────────────────

  /**
   * Intercetta OGNI cambio nel foglio prima che venga salvato.
   * Filtra per (x, y) così reagiamo solo ai cambi della nostra cella.
   *
   * Regola di business: "🚨 Critica" è ammessa solo se la colonna
   * Text (indice 0) ha un valore non vuoto nella stessa riga.
   */
  jxOnBeforeChange(e: JxCancellableEvent<JxChangePayload>): void {
    if (e.data.x !== this.context.x || e.data.y !== this.context.y) return;

    if (e.data.value === '🚨 Critica') {
      // Leggiamo il valore della colonna "Text" (col 0) per la stessa riga
      // tramite context.instance (JxTableComponent).
      const textVal = this.context.instance?.workbook?.getRow?.(this.context.y)?.[0];
      if (!textVal) {
        e.cancel(); // blocca il salvataggio
        this.addLog('❌ Critica vietata: testo mancante');
        this.cdr.markForCheck();
      }
    }
  }

  /** Notificato dopo che il valore è stato effettivamente salvato. */
  jxOnChange(payload: JxChangePayload): void {
    if (payload.x !== this.context.x || payload.y !== this.context.y) return;
    this.addLog(`✓ ${payload.oldValue ?? '—'} → ${payload.value}`);
    this.cdr.markForCheck();
  }

  /** Notificato quando un editor si apre su qualsiasi cella. */
  jxOnEditorOpen(payload: JxEditionStartPayload): void {
    if (payload.x !== this.context.x || payload.y !== this.context.y) return;
    this.addLog('📝 Editor aperto');
    this.cdr.markForCheck();
  }

  /**
   * Prima del salvataggio dell'editor.
   * Esempio: trasforma in maiuscolo qualunque valore di testo libero.
   * (questa cella usa click-cycle, ma l'hook è attivo anche per setValue diretto)
   */
  jxOnBeforeEditorClose(e: JxCancellableEvent<JxBeforeEditionEndPayload>): void {
    if (e.data.x !== this.context.x || e.data.y !== this.context.y) return;
    // Esempio: trasforma valore in uppercase se non è un livello riconosciuto
    const val = String(e.data.value ?? '');
    if (!this.levels.includes(val as PriorityLevel) && val.trim()) {
      e.setResult(val.toUpperCase());
    }
  }

  /** Dopo il salvataggio dell'editor. */
  jxOnEditorClose(payload: JxEditionEndPayload): void {
    if (payload.x !== this.context.x || payload.y !== this.context.y) return;
    this.addLog(`✅ Salvato: ${payload.value}`);
    this.cdr.markForCheck();
  }

  // ────────────────────────────────────────────────────────────────────────
  // Private
  // ────────────────────────────────────────────────────────────────────────

  private addLog(msg: string): void {
    this.log = [msg, ...this.log].slice(0, 3);
  }
}
