import { ChangeDetectorRef, Component, Input, OnDestroy, OnInit } from '@angular/core';
import { Subscription } from 'rxjs';
import { JxCustomHeaderBase, JxHeaderCellContext } from 'jx-cell';

/**
 * Demo — Budget Header Component
 *
 * Mostra il titolo della colonna con una mini progress bar che indica
 * quanto del budget configurato (default 500 €) è già stato consumato.
 * La barra cambia colore: verde < 60 %, giallo 60–89 %, rosso ≥ 90 %.
 *
 * Utilizzo:
 *   { title: 'Price', headerComponent: BudgetHeaderComponent, options: { budget: 300 } }
 *
 * `options.budget` è il tetto configurabile; se omesso usa DEFAULT_BUDGET.
 */
@Component({
  standalone: false,
  selector: 'app-budget-header',
  template: `
    <div class="bh-root" (click)="onSort()" [title]="tooltip">
      <span class="bh-title">{{ colTitle }}</span>
      <span *ngIf="colSortDir" class="bh-sort">
        {{ colSortDir === 'asc' ? '▲' : '▼' }}
      </span>

      <!-- Mini progress bar -->
      <div class="bh-bar-bg">
        <div
          class="bh-bar-fill"
          [class.bh-ok]="pct < 60"
          [class.bh-warn]="pct >= 60 && pct < 90"
          [class.bh-danger]="pct >= 90"
          [style.width.%]="barWidth"
        ></div>
      </div>

      <!-- Label: speso / budget -->
      <span class="bh-label" [class.bh-ok]="pct < 60" [class.bh-warn]="pct >= 60 && pct < 90" [class.bh-danger]="pct >= 90">
        {{ fmt(total) }} / {{ fmt(budget) }}
      </span>
    </div>
  `,
  styles: [`
    .bh-root {
      display: flex;
      flex-direction: column;
      align-items: stretch;
      cursor: pointer;
      gap: 2px;
      padding: 2px 0;
      user-select: none;
      min-width: 0;
    }
    .bh-title {
      font-weight: 700;
      font-size: 12px;
      text-align: center;
    }
    .bh-sort {
      font-size: 10px;
      color: #0078d4;
      text-align: center;
    }
    .bh-bar-bg {
      height: 5px;
      background: #e0e0e0;
      border-radius: 3px;
      overflow: hidden;
    }
    .bh-bar-fill {
      height: 100%;
      border-radius: 3px;
      transition: width 0.25s ease;
    }
    .bh-ok     { color: #155724; background: #28a745; }
    .bh-warn   { color: #856404; background: #ffc107; }
    .bh-danger { color: #721c24; background: #dc3545; }

    .bh-label {
      font-size: 9px;
      font-weight: 600;
      text-align: center;
      white-space: nowrap;
    }
  `],
})
export class BudgetHeaderComponent
  extends JxCustomHeaderBase
  implements OnInit, OnDestroy
{
  @Input() override context: JxHeaderCellContext = undefined!;

  private static readonly DEFAULT_BUDGET = 500;

  total  = 0;
  pct    = 0;
  /** Clamped a 100 per la barra visiva; `pct` può superare 100 per il colore. */
  barWidth = 0;

  private readonly sub = new Subscription();

  get budget(): number {
    return Number(this.context?.column?.options?.['budget'] ?? BudgetHeaderComponent.DEFAULT_BUDGET);
  }

  get colTitle(): string     { return this.context?.title ?? ''; }
  get colSortDir(): 'asc' | 'desc' | null { return this.context?.sortDirection ?? null; }
  get tooltip(): string {
    const over = this.pct - 100;
    if (over > 0) return `Sforato del ${over.toFixed(0)} % (${this.fmt(this.total - this.budget)} € in eccesso)`;
    return `${this.pct.toFixed(0)} % del budget utilizzato`;
  }

  onSort(): void { this.context?.sort?.(); }
  fmt(n: number): string { return `€ ${n.toFixed(2).replace(/\.?0+$/, '')}`; }

  constructor(private cdr: ChangeDetectorRef) { super(); }

  ngOnInit(): void {
    this.sub.add(
      this.context.api.data$.subscribe((data: any[][]) => {
        this.recompute(data);
        this.cdr.markForCheck();
      }),
    );
  }

  ngOnDestroy(): void {
    this.sub.unsubscribe();
  }

  private recompute(data: any[][]): void {
    const col = this.context.x;
    let sum = 0;
    for (const row of data) {
      const v = Number(row[col]);
      if (!Number.isNaN(v) && row[col] !== '' && row[col] != null) sum += v;
    }
    this.total   = sum;
    this.pct     = this.budget > 0 ? (sum / this.budget) * 100 : 0;
    this.barWidth = Math.min(100, this.pct);
  }
}
