interface LogEntry {
  time: string;
  type: 'info' | 'change' | 'nav' | 'error';
  message: string;
}

interface MockRow {
  id: number;
  name: string;
  email: string;
  role: string;
  salary: number;
  active: boolean;
  department: string;
  score: number;
}

const DEPARTMENTS = ['Engineering', 'Design', 'Marketing', 'Sales', 'HR', 'Finance', 'Support', 'Legal'];
const ROLES = ['Junior', 'Mid', 'Senior', 'Lead', 'Manager', 'Director'];
const FIRST = ['Alice','Bob','Carla','David','Elena','Frank','Giulia','Hans','Iris','Jack','Luca','Maria','Nora','Oscar','Paola'];
const LAST = ['Rossi','Bianchi','Ferrari','Ricci','Conti','De Luca','Mancini','Greco','Bruno','Gallo'];

function mockRow(i: number): MockRow {
  const first = FIRST[i % FIRST.length];
  const last = LAST[i % LAST.length];
  return {
    id: i + 1,
    name: `${first} ${last}`,
    email: `${first.toLowerCase()}.${last.toLowerCase()}${i}@company.com`,
    role: ROLES[i % ROLES.length],
    salary: 30000 + (i % 50) * 1000,
    active: i % 5 !== 0,
    department: DEPARTMENTS[i % DEPARTMENTS.length],
    score: Math.round((50 + (i % 50)) * 10) / 10,
  };
}

