  // ── Style ops ──────────────────────────────────────────────────────────
  private buildStylePayload(o: { color: string; backgroundColor: string; fontWeight: boolean; fontStyle: boolean; fontSize: string }) {
    const s: Record<string, string> = {};
    if (o.color)           s['color'] = o.color;
    if (o.backgroundColor) s['backgroundColor'] = o.backgroundColor;
    if (o.fontWeight)      s['fontWeight'] = 'bold';
    if (o.fontStyle)       s['fontStyle'] = 'italic';
    if (o.fontSize)        s['fontSize'] = o.fontSize;
    return s;
  }

  opSetCellStyle(): void {
    const s = this.buildStylePayload(this.ops.setCellStyle);
    this.instance?.setCellStyle(this.ops.setCellStyle.cell, s);
    this.showResult('setCellStyle', null);
  }

  opSetRowStyle(): void {
    const s = this.buildStylePayload(this.ops.setRowStyle);
    this.instance?.setRowStyle(this.ops.setRowStyle.row, s);
    this.showResult('setRowStyle', null);
  }

  opSetColStyle(): void {
    const s = this.buildStylePayload(this.ops.setColStyle);
    this.instance?.setColumnStyle(this.ops.setColStyle.col, s);
    this.showResult('setColumnStyle', null);
  }

  opSetBorder(): void {
    const o = this.ops.setBorder;
    const value = o.borderStyle === 'none' ? 'none' : `${o.width || '1'}px ${o.borderStyle} ${o.color}`;
    const prop = o.sides === 'all' ? 'border'
      : o.sides === 'top'    ? 'borderTop'
      : o.sides === 'bottom' ? 'borderBottom'
      : o.sides === 'left'   ? 'borderLeft'
      : 'borderRight';
    const style = { [prop]: value };
    if      (o.targetType === 'cell') this.instance?.setCellStyle(o.cell, style);
    else if (o.targetType === 'row')  this.instance?.setRowStyle(o.row, style);
    else                              this.instance?.setColumnStyle(o.col, style);
    this.showResult('setBorder', null);
  }

