  opParseCSV(): void {
    const result = this.instance?.parseCSV(this.ops.parseCSV.raw, this.ops.parseCSV.delimiter);
    this.showResult('parseCSV', result);
  }

  opImportCSV(): void {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.csv,text/csv,text/plain';
    input.onchange = () => {
      const file = input.files?.[0];
      if (!file || !this.instance) return;
      const reader = new FileReader();
      reader.onload = (e) => {
        const text = e.target?.result as string;
        const delimiter = this.cfg.csvDelimiter || ',';
        const rows = this.instance!.parseCSV(text, delimiter);
        let data: string[][] = rows;
        if (this.cfg.csvHeaders && data.length > 0) {
          data = data.slice(1); // salta la riga header
        }
        this.instance!.setData(data);
        this.showResult('importCSV', `${data.length} righe importate da ${file.name}`);
        this.log('info', `importCSV: ${data.length} righe da "${file.name}"`);
      };
      reader.readAsText(file);
    };
    input.click();
  }

