/**
 * ClearFormattingPlugin
 *
 * Toolbar plugin that removes all inline styles (bold, italic, color, bg, etc.)
 * from every cell in the current selection.
 *
 * ## Usage
 * ```ts
 * import { ClearFormattingPlugin } from './toolbar-plugins/clear-formatting.plugin';
 *
 * private readonly clearPlugin = new ClearFormattingPlugin();
 *
 * buildOptions(): JxCellOptions {
 *   return { ..., toolbarPlugins: [this.clearPlugin] };
 * }
 * ```
 */
import { JxToolbarPlugin, JxToolbarPluginContext, JxToolbarItem } from 'jx-cell';

export class ClearFormattingPlugin implements JxToolbarPlugin {
  readonly id = 'clear-formatting';
  readonly label = 'Clear Formatting';

  private wb: JxToolbarPluginContext['workbook'] | null = null;

  init(ctx: JxToolbarPluginContext): void {
    this.wb = ctx.workbook;
  }

  destroy(): void {
    this.wb = null;
  }

  readonly items: JxToolbarItem[] = [
    { type: 'divisor' },
    {
      type: 'i',
      content: 'format_clear',
      tooltip: 'Rimuovi formattazione',
      onclick: (_el, _obj, _item) => {
        const wb = this.wb;
        if (!wb) return;
        const sel = wb.getSelection();
        if (!sel) return;
        const { x1, y1, x2, y2 } = sel;
        for (let y = Math.min(y1, y2); y <= Math.max(y1, y2); y++) {
          for (let x = Math.min(x1, x2); x <= Math.max(x1, x2); x++) {
            const name = `${wb.getColumnName(x)}${y + 1}`;
            wb.resetStyle(name);
          }
        }
      },
    },
  ];
}
