/**
 * ExportCsvPlugin
 *
 * Toolbar plugin that triggers a CSV download of the entire grid via
 * `JxWorkbookService.download()`.
 *
 * Optionally you can set `includeHeaders = true` before registration to
 * include column headers in the exported file.
 *
 * ## Usage
 * ```ts
 * import { ExportCsvPlugin } from './toolbar-plugins/export-csv.plugin';
 *
 * private readonly exportPlugin = new ExportCsvPlugin();
 * // optional: this.exportPlugin.includeHeaders = true;
 *
 * buildOptions(): JxCellOptions {
 *   return { ..., toolbarPlugins: [this.exportPlugin] };
 * }
 * ```
 */
import { JxToolbarPlugin, JxToolbarPluginContext, JxToolbarItem } from 'jx-cell';

export class ExportCsvPlugin implements JxToolbarPlugin {
  readonly id = 'export-csv';
  readonly label = 'Export CSV';

  /** When true, column headers are included in the CSV file. Default: true. */
  includeHeaders = true;

  private wb: JxToolbarPluginContext['workbook'] | null = null;

  init(ctx: JxToolbarPluginContext): void {
    this.wb = ctx.workbook;
  }

  destroy(): void {
    this.wb = null;
  }

  readonly items: JxToolbarItem[] = [
    { type: 'divisor' },
    {
      type: 'i',
      content: 'download',
      tooltip: 'Esporta CSV',
      onclick: () => {
        this.wb?.download(this.includeHeaders);
      },
    },
  ];
}
