/**
 * HighlightRowPlugin
 *
 * Toolbar plugin that applies / removes a background-color highlight
 * to the entire row(s) of the current selection.
 *
 * Two buttons are added:
 *  - "Highlight row"  → applies a soft amber tint to all cells in the selected row(s)
 *  - "Clear row highlight" → removes the background from all cells in those row(s)
 *
 * ## Usage
 * ```ts
 * import { HighlightRowPlugin } from './toolbar-plugins/highlight-row.plugin';
 *
 * private readonly highlightPlugin = new HighlightRowPlugin();
 *
 * buildOptions(): JxCellOptions {
 *   return { ..., toolbarPlugins: [this.highlightPlugin] };
 * }
 * ```
 */
import { JxToolbarPlugin, JxToolbarPluginContext, JxToolbarItem } from 'jx-cell';

export class HighlightRowPlugin implements JxToolbarPlugin {
  readonly id = 'highlight-row';
  readonly label = 'Highlight Row';

  /** Colour used for the row highlight. Override before init() if desired. */
  highlightColor = '#fff3cd';

  private wb: JxToolbarPluginContext['workbook'] | null = null;

  init(ctx: JxToolbarPluginContext): void {
    this.wb = ctx.workbook;
  }

  destroy(): void {
    this.wb = null;
  }

  readonly items: JxToolbarItem[] = [
    { type: 'divisor' },
    {
      type: 'i',
      content: 'border_color',
      tooltip: 'Evidenzia riga',
      onclick: () => this._applyToRows({ 'background-color': this.highlightColor }),
    },
    {
      type: 'i',
      content: 'layers_clear',
      tooltip: 'Rimuovi evidenziazione riga',
      onclick: () => this._applyToRows({ 'background-color': '' }),
    },
  ];

  private _applyToRows(style: Record<string, string>): void {
    const wb = this.wb;
    if (!wb) return;
    const sel = wb.getSelection();
    if (!sel) return;
    const colCount: number = wb.getColumnCount();
    const { y1, y2 } = sel;
    for (let y = Math.min(y1, y2); y <= Math.max(y1, y2); y++) {
      for (let x = 0; x < colCount; x++) {
        const name = `${wb.getColumnName(x)}${y + 1}`;
        wb.setCellStyle(name, style as any);
      }
    }
  }
}
