import { Component, Input } from '@angular/core';
import { JxCustomCellBase, JxCustomCellContext } from 'jx-cell';

interface DemoRow extends Record<string, any> {
  customNumber?: number | string;
}

@Component({
  standalone: false,
  selector: 'app-custom-number-cell',
  template: `
    <input
      class="demo-custom-number"
      type="text"
      inputmode="decimal"
      [disabled]="!editable"
      [value]="draftValue"
      (mousedown)="hold($event)"
      (click)="hold($event)"
      (keydown)="onKey($event)"
      (input)="onInput($event)"
      (blur)="commitDraft($event)"
    />
  `,
})
export class CustomNumberCellComponent extends JxCustomCellBase<DemoRow> {
  @Input() override context: JxCustomCellContext<DemoRow> = undefined!;

  get draftValue(): string {
    return this.value === null || this.value === undefined ? '' : String(this.value);
  }

  hold(event?: Event): void {
    this.stopEvent(event);
  }

  onInput(event: Event): void {
    event.stopPropagation();
  }

  onKey(event: KeyboardEvent): void {
    event.stopPropagation();

    if (event.key === 'Enter') {
      event.preventDefault();
      this.commitDraft(event);
      this.focusCell();
    }

    if (event.key === 'Escape') {
      event.preventDefault();
      this.focusCell();
    }
  }

  commitDraft(event?: Event): void {
    event?.stopPropagation();

    const input = event?.target as HTMLInputElement | null;
    const raw = input?.value ?? '';

    if (raw === '') {
      this.commitValue('', false);
      return;
    }

    const value = Number(raw);
    this.commitValue(Number.isNaN(value) ? '' : value, false);
  }
}
