import { Component, Input, OnDestroy, OnInit } from '@angular/core';
import { Subscription } from 'rxjs';
import { JxCustomHeaderBase, JxHeaderCellContext } from 'jx-cell';

/**
 * Demo — Custom Header Component
 *
 * Mostra il titolo della colonna con sum e count dei valori numerici,
 * aggiornati live a ogni modifica dei dati.
 *
 * Utilizzo nella definizione colonna:
 *   { title: 'Quantity', headerComponent: ColumnStatsHeaderComponent }
 */
@Component({
  standalone: false,
  selector: 'app-column-stats-header',
  template: `
    <div class="csh-root" (click)="onSort()">
      <span class="csh-title">{{ colTitle }}</span>
      <span *ngIf="colSortDir" class="csh-sort">{{ colSortDir === 'asc' ? '▲' : '▼' }}</span>
      <span class="csh-stats" *ngIf="count > 0">
        Σ&nbsp;{{ fmt(sum) }}
        &nbsp;/&nbsp;avg&nbsp;{{ fmt(avg) }}
      </span>
    </div>
  `,
  styles: [`
    .csh-root {
      display: flex;
      flex-direction: column;
      align-items: center;
      cursor: pointer;
      gap: 1px;
      padding: 2px 0;
      user-select: none;
    }
    .csh-title {
      font-weight: 700;
      font-size: 12px;
      white-space: nowrap;
    }
    .csh-sort {
      font-size: 10px;
      color: #0078d4;
    }
    .csh-stats {
      font-size: 9px;
      color: #0078d4;
      font-weight: 600;
      white-space: nowrap;
    }
  `],
})
export class ColumnStatsHeaderComponent
  extends JxCustomHeaderBase
  implements OnInit, OnDestroy
{
  @Input() override context: JxHeaderCellContext = undefined!;

  sum   = 0;
  avg   = 0;
  count = 0;

  private readonly sub = new Subscription();

  /** Proxy espliciti per evitare errori strict-template col getter della base class. */
  get colTitle(): string { return this.context?.title ?? ''; }
  get colSortDir(): 'asc' | 'desc' | null { return this.context?.sortDirection ?? null; }
  onSort(): void { this.context?.sort?.(); }
  fmt(n: number): string { return n.toFixed(2).replace(/\.00$/, ''); }

  ngOnInit(): void {
    // Subscribe to the live data stream exposed by the workbook service.
    // `context.api` is the JxWorkbookService — `data$` emits whenever any
    // cell changes, so our stats stay perfectly in sync.
    this.sub.add(
      this.context.api.data$.subscribe((data: any[][]) => {
        this.recompute(data);
      }),
    );
  }

  ngOnDestroy(): void {
    this.sub.unsubscribe();
  }

  private recompute(data: any[][]): void {
    const col = this.context.x;
    let total = 0;
    let n = 0;
    for (const row of data) {
      const v = Number(row[col]);
      if (!Number.isNaN(v) && row[col] !== '' && row[col] != null) {
        total += v;
        n++;
      }
    }
    this.sum   = total;
    this.count = n;
    this.avg   = n > 0 ? total / n : 0;
  }
}
