import { ChangeDetectorRef, Component, Input, OnDestroy, OnInit } from '@angular/core';
import { Subscription } from 'rxjs';
import { JxCustomFooterBase, JxFooterCellContext } from 'jx-cell';

/**
 * Demo — Sum Gauge Footer Component
 *
 * Sostituisce il testo del footer con:
 *  - Valore calcolato (=formula o valore grezzo)
 *  - Mini progress bar rispetto a un obiettivo (target)
 *  - Etichetta colorata: verde / giallo / rosso
 *
 * Utilizzo:
 *   { title: 'Total', footerComponent: SumGaugeFooterComponent, options: { target: 1000 } }
 *
 * `options.target` è il traguardo configurabile (default 1000).
 */
@Component({
  standalone: false,
  selector: 'app-sum-gauge-footer',
  template: `
    <div class="sgf-root" [title]="tooltip">
      <!-- Valore calcolato -->
      <span class="sgf-value"
        [class.sgf-ok]="pct >= 100"
        [class.sgf-warn]="pct >= 60 && pct < 100"
        [class.sgf-low]="pct < 60">
        {{ fmtValue }}
      </span>

      <!-- Progress bar verso il target -->
      <div class="sgf-bar-bg">
        <div
          class="sgf-bar-fill"
          [class.sgf-ok]="pct >= 100"
          [class.sgf-warn]="pct >= 60 && pct < 100"
          [class.sgf-low]="pct < 60"
          [style.width.%]="barWidth"
        ></div>
      </div>

      <!-- Target -->
      <span class="sgf-target">/ {{ fmtTarget }}</span>
    </div>
  `,
  styles: [`
    .sgf-root {
      display: flex;
      flex-direction: column;
      align-items: stretch;
      gap: 2px;
      padding: 2px 2px;
      font-size: 11px;
      min-width: 0;
    }
    .sgf-value {
      font-weight: 700;
      font-size: 12px;
      text-align: right;
      white-space: nowrap;
    }
    .sgf-bar-bg {
      height: 4px;
      background: #e0e0e0;
      border-radius: 3px;
      overflow: hidden;
    }
    .sgf-bar-fill {
      height: 100%;
      border-radius: 3px;
      transition: width 0.25s ease;
    }
    .sgf-target {
      font-size: 9px;
      color: #888;
      text-align: right;
      white-space: nowrap;
    }

    /* State colours */
    .sgf-ok   { color: #155724; background: #28a745; }
    .sgf-warn { color: #856404; background: #ffc107; }
    .sgf-low  { color: #721c24; background: #dc3545; }

    /* For value span: background is irrelevant, just color */
    .sgf-value.sgf-ok   { color: #155724; background: transparent; }
    .sgf-value.sgf-warn { color: #856404; background: transparent; }
    .sgf-value.sgf-low  { color: #721c24; background: transparent; }
  `],
})
export class SumGaugeFooterComponent
  extends JxCustomFooterBase
  implements OnInit, OnDestroy
{
  @Input() override context: JxFooterCellContext = undefined!;

  private static readonly DEFAULT_TARGET = 1000;

  pct      = 0;
  barWidth = 0;
  numVal   = 0;

  private readonly sub = new Subscription();

  get target(): number {
    return Number(this.context?.column?.options?.['target'] ?? SumGaugeFooterComponent.DEFAULT_TARGET);
  }

  get fmtValue(): string { return this.fmt(this.numVal); }
  get fmtTarget(): string { return this.fmt(this.target); }

  get tooltip(): string {
    if (this.pct >= 100) return `Obiettivo raggiunto! (${this.pct.toFixed(0)} %)`;
    return `${this.pct.toFixed(0)} % dell'obiettivo (${this.fmt(this.target - this.numVal)} mancanti)`;
  }

  fmt(n: number): string {
    return `€ ${n.toFixed(2).replace(/\.00$/, '')}`;
  }

  constructor(private cdr: ChangeDetectorRef) { super(); }

  ngOnInit(): void {
    // Ascolta i cambi di dati per aggiornare il valore display in tempo reale.
    this.sub.add(
      this.context.api.data$.subscribe(() => {
        this.refresh();
      }),
    );
    // Aggiornamento iniziale.
    this.refresh();
  }

  ngOnDestroy(): void {
    this.sub.unsubscribe();
  }

  private refresh(): void {
    // Il valore display è aggiornato dal workbook dopo ogni render,
    // ma dobbiamo rileggere il footer calcolato via API.
    const raw = this.context.api.getFooter(this.context.fy, this.context.logicalCol, true);
    this.numVal  = Number(raw) || 0;
    this.pct     = this.target > 0 ? (this.numVal / this.target) * 100 : 0;
    this.barWidth = Math.min(100, this.pct);
    this.cdr.markForCheck();
  }
}
